reference_solution:
def remove_k_adjacent_duplicates(s, k):
 stack=[]
 for char in s:
  if stack and stack[-1][0]==char:stack[-1][1]+=1
  else:stack.append([char,1])
  if stack[-1][1]==k:stack.pop()
 return ''.join(char*count for char,count in stack)

